package cn.reviewsystem.recommend;

import java.math.*;
import java.sql.ResultSet;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

@Service
public class RecommendationService {
 private static final BigDecimal HUNDRED=new BigDecimal("100");
 private static final MathContext MC=MathContext.DECIMAL128;
 private final JdbcTemplate db;private final VersionedRecommendationConfig cfg;private final Clock clock;
 @Autowired
 public RecommendationService(JdbcTemplate db,VersionedRecommendationConfig cfg){this(db,cfg,Clock.systemUTC());}
 RecommendationService(JdbcTemplate db,VersionedRecommendationConfig cfg,Clock clock){this.db=db;this.cfg=cfg;this.clock=clock;}

 public RecommendationDtos.Response recommend(long userId,int requested){
  if(requested<1||requested>20)throw new IllegalArgumentException("count must be between 1 and 20");
  OffsetDateTime now=OffsetDateTime.ofInstant(clock.instant(),ZoneOffset.UTC);
  List<Kp> all=knowledge(userId,now);List<Kp> review=all.stream().filter(k->k.n>=cfg.reviewMinimumN()).sorted(reviewOrder()).toList();
  List<Kp> diagnostic=all.stream().filter(k->k.n<cfg.reviewMinimumN()).sorted(Comparator.comparingInt((Kp k)->k.n).thenComparingLong(k->k.id)).toList();
  boolean newUser=all.stream().allMatch(k->k.n==0);if(newUser&&diagnostic.size()>cfg.newUserKnowledgeLimit())diagnostic=diagnostic.subList(0,cfg.newUserKnowledgeLimit());
  int reviewTarget=Math.min(cfg.reviewSlots(),requested),diagnosticTarget=Math.min(cfg.diagnosticSlots(),requested-reviewTarget);
  PickResult rp=pick(userId,review,"REVIEW",reviewTarget,now,new HashSet<>());Set<Long> used=new HashSet<>(rp.questionIds());
  PickResult dp=pick(userId,diagnostic,"DIAGNOSTIC",diagnosticTarget,now,used);used.addAll(dp.questionIds());
  int missing=requested-rp.items.size()-dp.items.size();
  if(missing>0){PickResult extraD=pick(userId,diagnostic,"DIAGNOSTIC",missing,now,used);dp=dp.append(extraD);used.addAll(extraD.questionIds());missing=requested-rp.items.size()-dp.items.size();}
  if(missing>0){PickResult extraR=pick(userId,review,"REVIEW",missing,now,used);rp=rp.append(extraR);used.addAll(extraR.questionIds());}
  List<RecommendationDtos.Item> items=new ArrayList<>();items.addAll(rp.items);items.addAll(dp.items);for(int i=0;i<items.size();i++){var x=items.get(i);items.set(i,new RecommendationDtos.Item(x.questionId(),x.questionNo(),x.knowledgeId(),x.knowledgeCode(),i,x.reason(),x.questionVersionId(),x.questionType(),x.origin()));}
  List<RecommendationDtos.Shortfall> shortfall=new ArrayList<>();int totalMissing=requested-items.size();if(totalMissing>0){String pool=rp.items.size()<reviewTarget?"REVIEW":dp.items.size()<diagnosticTarget?"DIAGNOSTIC":"TOTAL";shortfall.add(new RecommendationDtos.Shortfall(pool,totalMissing,"insufficient ACTIVE questions after cross-pool supplementation"));}
  List<RecommendationDtos.PlannedKnowledge> plan=new ArrayList<>();Set<String> plannedIds=new HashSet<>();for(RecommendationDtos.Item item:items){if(plannedIds.add(item.knowledgeId()))plan.add(new RecommendationDtos.PlannedKnowledge(item.knowledgeId(),item.knowledgeCode(),item.reason().pool(),item.reason().priority(),item.reason().n()));}
  boolean updating=Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM rs_change_event e JOIN rs_practice p ON p.id=e.source_id WHERE e.event_type='PRACTICE_SUBMITTED' AND p.user_id=? AND e.state<>'DONE')",Boolean.class,userId));
  return new RecommendationDtos.Response(cfg.ruleVersion(),updating,parameters(),plan,List.copyOf(rp.items),List.copyOf(dp.items),List.copyOf(items),List.copyOf(shortfall));
 }

 private List<Kp> knowledge(long user,OffsetDateTime now){return db.query("SELECT k.id,k.code,COALESCE(s.n,0),s.final_score,s.rule_score,s.latest_practice_at FROM rs_knowledge_point k JOIN rs_chapter c ON c.id=k.chapter_id LEFT JOIN rs_mastery_current mc ON mc.user_id=? AND mc.knowledge_id=k.id LEFT JOIN rs_mastery_snapshot s ON s.id=mc.snapshot_id WHERE k.subject_id=1 AND k.enabled AND c.enabled AND EXISTS(SELECT 1 FROM rs_question q JOIN rs_question_version v ON v.id=q.current_version_id WHERE q.status='ACTIVE' AND v.knowledge_point_id=k.id) ORDER BY k.id",(r,i)->kp(r,user,now),user);}
 private Kp kp(ResultSet r,long user,OffsetDateTime now)throws java.sql.SQLException{long id=r.getLong(1);int n=r.getInt(3);BigDecimal fin=r.getBigDecimal(4),rule=r.getBigDecimal(5);OffsetDateTime latest=r.getObject(6,OffsetDateTime.class);List<Ev> ev=evidence(user,id);int numerator=0,denominator=0;for(Ev e:ev)if(e.y!=null){denominator++;BigDecimal threshold=Set.of("CHOICE","FILL").contains(e.type)?new BigDecimal("0.5"):new BigDecimal("0.6");if(e.y.compareTo(threshold)<0)numerator++;}BigDecimal w=n>=cfg.reviewMinimumN()&&fin!=null?BigDecimal.ONE.subtract(fin.divide(HUNDRED,MC)):BigDecimal.ZERO;BigDecimal d=latest==null?BigDecimal.ZERO:seconds(latest,now).divide(new BigDecimal("86400"),MC);BigDecimal t=d.divide(new BigDecimal(cfg.timeWindowDays()),MC).min(BigDecimal.ONE).max(BigDecimal.ZERO);BigDecimal error=denominator==0?BigDecimal.ZERO:new BigDecimal(numerator).divide(new BigDecimal(denominator),MC);BigDecimal p=cfg.weaknessWeight().multiply(w,MC).add(cfg.timeWeight().multiply(t,MC),MC).add(cfg.errorWeight().multiply(error,MC),MC);return new Kp(id,r.getString(2),n,fin,rule,latest,d,w,t,error,p,numerator,denominator,ev.stream().map(e->e.id).toList());}
 private List<Ev> evidence(long user,long kp){return db.query("SELECT id,question_id,question_type,result_y,submitted_at FROM (SELECT DISTINCT ON (question_id) id,question_id,question_type,result_y,submitted_at FROM rs_evidence WHERE user_id=? AND knowledge_id=? AND NOT revoked ORDER BY question_id,submitted_at DESC,id DESC) selected ORDER BY submitted_at DESC,id DESC LIMIT ?",(r,i)->new Ev(r.getLong(1),r.getLong(2),r.getString(3),r.getBigDecimal(4),r.getObject(5,OffsetDateTime.class)),user,kp,cfg.evidenceWindow());}
 private Comparator<Kp> reviewOrder(){return Comparator.comparing((Kp k)->k.p,Comparator.reverseOrder()).thenComparing(k->k.latest,Comparator.nullsFirst(Comparator.naturalOrder())).thenComparingLong(k->k.id);}
 private PickResult pick(long user,List<Kp> knowledge,String pool,int slots,OffsetDateTime now,Set<Long> already){if(slots<=0||knowledge.isEmpty())return new PickResult(new ArrayList<>(),new HashSet<>());List<Kp> active=new ArrayList<>();int initial=pool.equals("REVIEW")?Math.min(cfg.reviewInitialKnowledge(),knowledge.size()):knowledge.size();active.addAll(knowledge.subList(0,initial));int next=initial;Map<Long,List<Question>> normal=new HashMap<>(),relaxed=new HashMap<>();for(Kp k:knowledge){List<Question> ordered=questions(user,k,now);normal.put(k.id,new ArrayList<>(ordered.stream().filter(q->!q.cooling).toList()));relaxed.put(k.id,new ArrayList<>(ordered.stream().filter(q->q.cooling).toList()));}List<RecommendationDtos.Item> out=new ArrayList<>();Set<Long> used=new HashSet<>(already);while(out.size()<slots){boolean progress=round(active,normal,pool,false,used,out,slots);if(out.size()>=slots)break;if(!progress&&next<knowledge.size()){active.add(knowledge.get(next++));continue;}if(!progress)break;}while(out.size()<slots){boolean progress=round(active,relaxed,pool,true,used,out,slots);if(out.size()>=slots)break;if(!progress&&next<knowledge.size()){active.add(knowledge.get(next++));continue;}if(!progress)break;}Set<Long> selected=new HashSet<>();out.forEach(i->selected.add(Long.parseLong(i.questionId())));return new PickResult(out,selected);}
 private boolean round(List<Kp> active,Map<Long,List<Question>> source,String pool,boolean relaxed,Set<Long> used,List<RecommendationDtos.Item> out,int slots){boolean progress=false;for(Kp k:active){if(out.size()>=slots)break;List<Question> list=source.get(k.id);while(!list.isEmpty()&&used.contains(list.get(0).id))list.remove(0);if(list.isEmpty())continue;Question q=list.remove(0);if(!used.add(q.id))throw new IllegalStateException("duplicate recommended questionId "+q.id);var facts=new RecommendationDtos.Facts(pool,k.p,k.w,k.t,k.error,k.finalScore,k.ruleScore,k.n,k.days,k.errNum,k.errDen,k.evidenceIds.stream().map(String::valueOf).toList(),q.category,relaxed,relaxed?"24-hour cooldown relaxed because non-cooled candidates could not fill requested slots":null,cfg.ruleVersion());out.add(new RecommendationDtos.Item(String.valueOf(q.id),q.no,String.valueOf(k.id),k.code,out.size(),facts,String.valueOf(q.versionId),q.type,q.origin));progress=true;}return progress;}
 private List<Question> questions(long user,Kp k,OffsetDateTime now){return db.query("SELECT q.id,q.question_no,h.result_y,h.submitted_at,h.question_type,v.id,v.type,q.origin FROM rs_question q JOIN rs_question_version v ON v.id=q.current_version_id JOIN rs_knowledge_point k ON k.id=v.knowledge_point_id JOIN rs_chapter c ON c.id=k.chapter_id LEFT JOIN LATERAL (SELECT e.result_y,e.submitted_at,e.question_type FROM rs_evidence e WHERE e.user_id=? AND e.knowledge_id=k.id AND e.question_id=q.id AND NOT e.revoked ORDER BY e.submitted_at DESC,e.id DESC LIMIT 1) h ON TRUE WHERE q.status='ACTIVE' AND k.id=? AND k.enabled AND c.enabled ORDER BY q.question_no,q.id",(r,i)->question(r,now),user,k.id).stream().sorted(questionOrder()).toList();}
 private Question question(ResultSet r,OffsetDateTime now)throws java.sql.SQLException{BigDecimal y=r.getBigDecimal(3);OffsetDateTime at=r.getObject(4,OffsetDateTime.class);String type=r.getString(5);String category;if(at==null)category="UNSEEN";else{BigDecimal threshold=Set.of("CHOICE","FILL").contains(type)?new BigDecimal("0.5"):new BigDecimal("0.6");category=y==null||y.compareTo(threshold)<0?"RECENT_WRONG":"LONGEST_UNSEEN";}boolean cooling=at!=null&&at.isAfter(now.minusHours(cfg.cooldownHours()));return new Question(r.getLong(1),r.getString(2),category,at,cooling,r.getLong(6),r.getString(7),r.getString(8));}
 private Comparator<Question> questionOrder(){return (a,b)->{int ca=categoryRank(a),cb=categoryRank(b);if(ca!=cb)return Integer.compare(ca,cb);if(a.at!=null&&b.at!=null){int time=ca==1?b.at.compareTo(a.at):a.at.compareTo(b.at);if(time!=0)return time;}int no=a.no.compareTo(b.no);return no!=0?no:Long.compare(a.id,b.id);};}
 private static int categoryRank(Question q){return switch(q.category){case "UNSEEN"->0;case "RECENT_WRONG"->1;default->2;};}
 private static BigDecimal seconds(OffsetDateTime a,OffsetDateTime b){return new BigDecimal(Math.max(0,ChronoUnit.MILLIS.between(a,b))).divide(new BigDecimal("1000"),MC);}
 private RecommendationDtos.Parameters parameters(){return new RecommendationDtos.Parameters(cfg.weaknessWeight(),cfg.timeWeight(),cfg.errorWeight(),cfg.timeWindowDays(),cfg.evidenceWindow(),cfg.cooldownHours(),cfg.defaultCount(),cfg.reviewSlots(),cfg.diagnosticSlots(),cfg.reviewInitialKnowledge(),cfg.newUserKnowledgeLimit(),cfg.reviewMinimumN());}
 record Ev(long id,long questionId,String type,BigDecimal y,OffsetDateTime at){}record Kp(long id,String code,int n,BigDecimal finalScore,BigDecimal ruleScore,OffsetDateTime latest,BigDecimal days,BigDecimal w,BigDecimal t,BigDecimal error,BigDecimal p,int errNum,int errDen,List<Long> evidenceIds){}record Question(long id,String no,String category,OffsetDateTime at,boolean cooling,long versionId,String type,String origin){}record PickResult(List<RecommendationDtos.Item> items,Set<Long> questionIds){PickResult append(PickResult other){List<RecommendationDtos.Item> both=new ArrayList<>(items);both.addAll(other.items);Set<Long> ids=new HashSet<>(questionIds);ids.addAll(other.questionIds);return new PickResult(both,ids);}}
}
